INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(35511, 'Luke 4:28', 'Luke', 4, 28, 'کله چې په کنیسه کې خلکو دا خبرې واورېدلې نو ډېر په قهر شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke4_verse_28.mp3', '', 1761754199, 1761754199),
(35512, 'Luke 4:29', 'Luke', 4, 29, 'هغوی راپاڅېدل او عیسی یې د ښار څخه وویست او د هغې غونډۍ سرته یې وخېژاوه چې دا ښار ورباندې جوړ شوی ؤ، ترڅو لاندې یې وغورځوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke4_verse_29.mp3', '', 1761754199, 1761754199),
(35513, 'Luke 4:30', 'Luke', 4, 30, 'خو هغه د هغوی له منځ څخه تېر شو او لاړ. عیسی پېریانو نیولي سړي ته شفا ورکوي (مرقوس ۱‏:‌۲۱‌‏-‌۲۸)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke4_verse_30.mp3', '', 1761754199, 1761754199),
(35514, 'Luke 4:31', 'Luke', 4, 31, 'بیا عیسی کپرناحوم ته چې د جلیل یو ښار ؤ لاړ او د سبت په ورځ یې خلکو ته تعلیم ورکاوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke4_verse_31.mp3', '', 1761754199, 1761754199),
(35515, 'Luke 4:32', 'Luke', 4, 32, 'خلک د هغه په تعلیم حیران شول، ځکه چې په پوره اختیار سره یې خبرې کولې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke4_verse_32.mp3', '', 1761754199, 1761754199),
(35516, 'Luke 4:33', 'Luke', 4, 33, 'په کنیسه کې یو سړی ؤ چې پېریانو نیولی ؤ او په لوړ اواز یې چیغې ووهلې:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke4_verse_33.mp3', '', 1761754199, 1761754199),
(35517, 'Luke 4:34', 'Luke', 4, 34, '«ای ناصري عیسی! زمونږ سره څه کار لرې؟ ته راغلی یې چې مونږ تباه کړې؟ زه دې پېژنم چې ته څوک یې، ته د خدای سپېڅلی یې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke4_verse_34.mp3', '', 1761754199, 1761754199),
(35518, 'Luke 4:35', 'Luke', 4, 35, 'عیسی پېري ته حکم وکړ: «غلی شه او د دې سړي څخه راووځه.» پېري هغه سړی د هغوی په مخکې په ځمکه راوویشت او بې له دې چې کوم زیان ورته ورسوي ورڅخه ووت.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke4_verse_35.mp3', '', 1761754199, 1761754199),
(35519, 'Luke 4:36', 'Luke', 4, 36, 'ټول خلک حیران شول او یو بل ته یې ویل: «دا څه خبره ده چې دا سړی په پوره اختیار او قدرت سره پېریانو ته امر کوي او هغوی وځي؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke4_verse_36.mp3', '', 1761754199, 1761754199),
(35520, 'Luke 4:37', 'Luke', 4, 37, 'او په دې ډول دا خبره په ټوله سیمه کې خپره شوه. عیسی ډېرو خلکو ته شفا ورکوي (متي ۸‏:‌۱۴‌‏-‌۱۷ او مرقوس ۱‏:‌۲۹‌‏-‌۳۴)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke4_verse_37.mp3', '', 1761754199, 1761754199),
(35521, 'Luke 4:38', 'Luke', 4, 38, 'عیسی د کنیسې څخه راووت او د شمعون کور ته لاړ. د شمعون خواښې سختې تبې نیولې وه او هغوی د عیسی څخه وغوښتل چې د هغې سره مرسته وکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke4_verse_38.mp3', '', 1761754199, 1761754199),
(35522, 'Luke 4:39', 'Luke', 4, 39, 'عیسی لاړ او د هغې په خوا کې ودرېده او تبې ته یې امر وکړ چې هغه پرېږدي. تبې هغه ښځه پرېښودله، بیا ښځه سمدلاسه پاڅېدله او د هغوی خدمت یې پیل کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke4_verse_39.mp3', '', 1761754199, 1761754199),
(35523, 'Luke 4:40', 'Luke', 4, 40, 'د لمر پرېوتولو په وخت کې ‎خلکو خپل ناروغان چې په ډول ډول ناروغیو اخته وو عیسی ته راوستل. هغه په هر یو باندې خپل لاس کېښود او ټول یې روغ کړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke4_verse_40.mp3', '', 1761754199, 1761754199),
(35524, 'Luke 4:41', 'Luke', 4, 41, 'د ډېرو خلکو څخه پېریان ووتل او چیغې یې وهلې: «ته د خدای زوی یې.» خو عیسی پېریانو ته حکم وکړ او هغوی یې پرېنښودل چې خبرې وکړي، ځکه هغوی پوهېدل چې هغه مسیح دی. عیسی په کنیسه کې وعظ کوي (مرقوس ۱‏:‌۳۵‌‏-‌۳۹)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke4_verse_41.mp3', '', 1761754199, 1761754199),
(35525, 'Luke 4:42', 'Luke', 4, 42, 'کله چې سهار شو، نو عیسی د ښار څخه روان شو او یو ګوښه ځای ته لاړ. خلکو هغه لټاوه او چې کله یې پیدا کړ، نو کوښښ یې وکړ چې د هغه د تللو مخه ونیسي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke4_verse_42.mp3', '', 1761754199, 1761754199),
(35526, 'Luke 4:43', 'Luke', 4, 43, 'خو هغه ورته وویل: «زه باید نورو ښارونو ته هم د خدای د پاچاهۍ زېری ورسوم، ځکه چې د همدې کار دپاره رالېږل شوی یم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke4_verse_43.mp3', '', 1761754199, 1761754199),
(35527, 'Luke 4:44', 'Luke', 4, 44, 'نو هغه د یهودیې په ټولو کنیسو کې وعظ کاوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke4_verse_44.mp3', '', 1761754199, 1761754199),
(35528, 'Acts 28:1', 'Acts', 28, 1, 'کله چې مونږ روغ رمټ د بحیرې غاړې ته ورسېدلو، نو پوه شولو چې دا د مالتا په نوم جزیره ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts28_verse_1.mp3', '', 1761754199, 1761754199),
(35529, 'Acts 28:2', 'Acts', 28, 2, 'د هغه ځای خلکو په مونږ ډېره مهرباني وکړه او څرنګه چې هوا سړه وه او باران ورېده، نو اور یې راته بل کړ او مونږ ټولو ته یې تود هرکلی ووایه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts28_verse_2.mp3', '', 1761754199, 1761754199),
(35530, 'Acts 28:3', 'Acts', 28, 3, 'پولوس یو څه لرګي راټول کړل او هغه یې اور ته واچول او د اور د ګرموالي له امله یو زهرجن مار راووت او د هغه د لاس پورې ونښته.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts28_verse_3.mp3', '', 1761754199, 1761754199),
(35531, 'Acts 28:4', 'Acts', 28, 4, 'کله چې د هغه ځای خلکو ولیدل چې د پولوس په لاس پورې مار ځوړند دی، نو یو بل ته یې سره وویل: «دا سړی به خامخا قاتل وي. که څه هم هغه له بحیرې څخه وژغورل شو، خو الهي عدالت به هغه ژوندی پرېنږدي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts28_verse_4.mp3', '', 1761754199, 1761754199),
(35532, 'Acts 28:5', 'Acts', 28, 5, 'خو پولوس هغه مار اور ته ورګوزار کړ او کوم زیان ورته ونه رسېده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts28_verse_5.mp3', '', 1761754199, 1761754199),
(35533, 'Acts 28:6', 'Acts', 28, 6, 'هغوی په دې تمه وو چې پولوس به زر وپړسیږي او یا به ناڅاپه راولویږي او مړ به شي. خو کله چې هغوی ډېر انتظار وویست او ویې لیدل چې په هغه باندې هېڅ هم ونه شول، نو فکرونه یې بدل شول او ویې ویل: «دا هم یو خدای دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts28_verse_6.mp3', '', 1761754199, 1761754199),
(35534, 'Acts 28:7', 'Acts', 28, 7, 'هغه ځای ته نژدې د هغې جزیرې د حاکم پوبلیوس ځمکې وې. هغه په مهربانۍ سره مونږ ته هرکلی ووایه او درې ورځې یې په خپل کور کې مېلمانه کړو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts28_verse_7.mp3', '', 1761754199, 1761754199),
(35535, 'Acts 28:8', 'Acts', 28, 8, 'هغه وخت د پوبلیوس پلار ناروغه پروت ؤ. هغه تبه لرله او د پېچ په ناروغۍ اخته ؤ. پولوس د هغه کوټې ته ننوت، د هغه دپاره یې دعا وکړه، خپل لاس یې ورباندې کېښود او هغه ته یې شفا ورکړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts28_verse_8.mp3', '', 1761754199, 1761754199),
(35536, 'Acts 28:9', 'Acts', 28, 9, 'کله چې دا کار وشو، نو د جزیرې نور ناروغان هم راغلل او روغ شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts28_verse_9.mp3', '', 1761754199, 1761754199),
(35537, 'Acts 28:10', 'Acts', 28, 10, 'هغوی مونږ ته ډېر سوغاتونه راکړل او کله چې مونږ غوښتل لاړ شو، نو کومو شیانو ته چې په سفر کې مو ورته اړتیا لرله، هغه یې مونږ ته کشتۍ ته راوړل. روم ته د پولوس رسېدل', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts28_verse_10.mp3', '', 1761754199, 1761754199),
(35538, 'Acts 28:11', 'Acts', 28, 11, 'درې میاشتې وروسته د سکندریې په یوه کشتۍ کې چې د دوه غبرګوني خدایانو کیستر او پولوکس توږل شوې مجسمې ورباندې لګېدلې وې او ژمی یې په هغې جزیرې کې تېر کړی ؤ، لاړو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts28_verse_11.mp3', '', 1761754199, 1761754199),
(35539, 'Acts 28:12', 'Acts', 28, 12, 'مونږ د سراکیوس ښار ته ورسېدلو او درې ورځې هلته پاتې شولو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts28_verse_12.mp3', '', 1761754199, 1761754199),
(35540, 'Acts 28:13', 'Acts', 28, 13, 'بیا د هغه ځای څخه په کشتۍ کې روان شولو او د ریغیون ښار ته ورسېدلو. بیا یوه ورځ وروسته جنوبي بادونه پیل شول او په دوو ورځو کې د پوتیولي بندر ته ورسېدلو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts28_verse_13.mp3', '', 1761754199, 1761754199),
(35541, 'Acts 28:14', 'Acts', 28, 14, 'په هغه ځای کې مونږ ځینې ایمانداران ولیدل او هغوی زمونږ څخه وغوښتل چې د یوې هفتې دپاره ورسره پاتې شو. په دې ډول مونږ روم ته ورسېدلو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts28_verse_14.mp3', '', 1761754199, 1761754199),
(35542, 'Acts 28:15', 'Acts', 28, 15, 'کله چې د روم ایمانداران زمونږ د راتللو څخه خبر شول، نو هغوی د اپیاس تر بازاره او هغه ځای پورې چې د درې مېلمستونونو په نوم یادېده، زمونږ لیدلو ته راغلل. کله چې پولوس هغوی ولیدل، نو د خدای شکر یې وویست او زړور شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts28_verse_15.mp3', '', 1761754199, 1761754199),
(35543, 'Acts 28:16', 'Acts', 28, 16, 'کله چې مونږ روم ته ورسېدلو، نو پولوس ته اجازه ورکړل شوه چې د یو رومي عسکر سره چې د هغه ساتنه یې کوله، په یو شخصي کور کې واوسیږي. پولوس په روم کې وعظ کوي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts28_verse_16.mp3', '', 1761754199, 1761754199),
(35544, 'Acts 28:17', 'Acts', 28, 17, 'درې ورځې وروسته پولوس د هغه ځای د یهودیانو مشران غونډې ته راوغوښتل. کله چې هغوی سره راټول شول، نو ورته ویې ویل: «ای زما ورونو، که څه هم ما د خپلو خلکو او د خپلو نیکونو د دودونو او دستورونو په خلاف کوم کار نه دی کړی، خو بیاهم زه په اورشلیم کې بندي شوم او رومیانو ته وسپارل شوم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts28_verse_17.mp3', '', 1761754199, 1761754199),
(35545, 'Acts 28:18', 'Acts', 28, 18, 'کله چې رومیانو زما څخه څېړنې وکړې نو غوښتل یې چې ما ازاد کړي، ځکه هغوی پوه شول چې ما داسې کوم کار نه دی کړی چې د مرګ سزا دې راته راکړل شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts28_verse_18.mp3', '', 1761754199, 1761754199),
(35546, 'Acts 28:19', 'Acts', 28, 19, 'خو کله چې د یهودیانو مشرانو مخالفت وکړ، نو زه دې ته مجبور شوم چې امپراتور ته عرض وکړم. بې له شکه ما سره هېڅ داسې څه نشته چې د خپل قوم په خلاف یې ووایم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts28_verse_19.mp3', '', 1761754199, 1761754199),
(35547, 'Acts 28:20', 'Acts', 28, 20, 'نو له دې امله مې راوغوښتلئ چې تاسو ووینم او خبرې درسره وکړم چې زه د هغه چا په خاطر په زولنو تړل شوی یم چې د اسراییلو خلک ورته هیله‌مند دي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts28_verse_20.mp3', '', 1761754199, 1761754199),
(35548, 'Acts 28:21', 'Acts', 28, 21, 'یهودي مشرانو ځواب ورکړ: «مونږ ته ستا په هکله له یهودیې څخه کوم لیک نه دی رارسېدلی او نه زمونږ د یهودي ورونو څخه کوم څوک دلته راغلی دی چې ستا په هکله یې مونږ ته خبر راوړی وي او یا یې ستا په هکله کومه بده خبره کړې وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts28_verse_21.mp3', '', 1761754199, 1761754199),
(35549, 'Acts 28:22', 'Acts', 28, 22, 'خو مونږ غواړو چې ستا نظر واورو، ځکه مونږ پوهېږو چې خلک په هرځای کې د دې ډلې په خلاف خبرې کوي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts28_verse_22.mp3', '', 1761754199, 1761754199),
(35550, 'Acts 28:23', 'Acts', 28, 23, 'نو هغوی د پولوس سره یوه ورځ وټاکله او ډېر خلک د هغه کور ته راغلل. د سهار نه تر ماښامه پورې پولوس د هغوی سره د خدای د پاچاهۍ په هکله خپل پیغام بیان کړ او شاهدي یې ورکړه او کوښښ یې وکړ چې د موسی د شریعت او د پیغمبرانو له کتابونو څخه په کار اخیستلو سره هغوی د عیسی په هکله قانع کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts28_verse_23.mp3', '', 1761754199, 1761754199),
(35551, 'Acts 28:24', 'Acts', 28, 24, 'ځینې د هغه په خبرو قانع شول، خو نورو ورباندې باور ونه کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts28_verse_24.mp3', '', 1761754199, 1761754199),
(35552, 'Acts 28:25', 'Acts', 28, 25, 'هغوی په خپل منځ کې سره بې‌اتفاقه شول او روان شول. خو له تګ څخه مخکې پولوس دا خبره وکړه: «روح القدس د اشعیا نبي په وسیله ستاسو نیکونو ته څنګه ښه ویلي دي:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts28_verse_25.mp3', '', 1761754199, 1761754199),
(35553, 'Acts 28:26', 'Acts', 28, 26, 'دې قوم ته ورشه او ورته ووایه: تاسو به بیا بیا اورئ، خو پوه به نه شئ. تاسو به ګورئ، خو څه به نه وینئ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts28_verse_26.mp3', '', 1761754199, 1761754199),
